// A live player that keeps its own buffer small.
//
// A plain <audio src> decides for itself how much to buffer before it starts
// and never catches up — seconds behind live. This fetches the stream instead,
// hands each piece to Media Source Extensions as it arrives, and holds the
// playhead a fraction of a second behind the newest audio: nudging the rate up
// a little when it drifts, jumping only when it has fallen far behind.
// The stream sits beside this page, whether the page was opened at the
// endpoint's bare address (an hkp-node mount has no trailing slash) or below it.
const PAGE = location.href.replace(/[?#].*$/, "");
const STREAM = new URL("live.mp3", PAGE.endsWith("/") ? PAGE : PAGE + "/").toString();
const TARGET = 0.4; // seconds of audio kept ahead of the playhead
const NUDGE = 0.7;  // beyond this, play 5% faster until back at the target
const JUMP = 2.0;   // beyond this, jump to the target

const Source = window.ManagedMediaSource || window.MediaSource;
const canStream = !!Source && Source.isTypeSupported("audio/mpeg");
const toggle = document.getElementById("toggle");
const status = document.getElementById("status");
let session = null;

toggle.addEventListener("click", () => (session ? stop() : start()));

// ?autoplay starts without a tap, where the browser allows it (a kiosk, a
// desktop that has allowed this site); ?debug logs what the status line says.
const options = new URLSearchParams(location.search);
if (options.has("autoplay")) start();

function say(text) {
  status.textContent = text;
  if (options.has("debug")) console.log("[player]", text);
}

function start() {
  toggle.setAttribute("aria-pressed", "true");
  toggle.textContent = "Stop";
  session = canStream ? streamed() : plain();
}

function stop() {
  session?.close();
  session = null;
  toggle.setAttribute("aria-pressed", "false");
  toggle.textContent = "Listen";
  say("Tap to listen");
}

// Without MSE: the browser's own player, with whatever delay it chooses.
function plain() {
  const audio = new Audio(STREAM);
  audio.play().catch((e) => say(String(e)));
  say("Live (this browser buffers on its own)");
  return { close: () => { audio.pause(); audio.removeAttribute("src"); audio.load(); } };
}

function streamed() {
  const audio = document.createElement("audio");
  audio.disableRemotePlayback = true; // required by ManagedMediaSource
  const media = new Source();
  audio.src = URL.createObjectURL(media);
  const abort = new AbortController();
  let closed = false;
  let timer = null;

  // play() inside the click keeps the gesture a browser asks for before sound.
  audio.play().catch(() => {});
  say("Connecting…");

  media.addEventListener("sourceopen", async () => {
    const buffer = media.addSourceBuffer("audio/mpeg");
    buffer.mode = "sequence"; // live: each piece follows the last, whatever its timestamps
    const pending = [];
    const feed = () => {
      if (closed || buffer.updating || !pending.length) return;
      try {
        buffer.appendBuffer(pending[0]);
        pending.shift();
      } catch (e) {
        // Full: drop what is long played and try again on the next update.
        if (e.name === "QuotaExceededError" && audio.currentTime > 1) buffer.remove(0, audio.currentTime - 1);
        else throw e;
      }
    };
    buffer.addEventListener("updateend", () => {
      // Keep a few seconds behind the playhead, not the whole broadcast.
      const played = audio.currentTime - 5;
      if (!buffer.updating && played > 1 && buffer.buffered.length && buffer.buffered.start(0) < played) {
        buffer.remove(0, played);
        return;
      }
      feed();
    });

    try {
      const response = await fetch(STREAM, { signal: abort.signal, cache: "no-store" });
      // Nothing answers here: the board is not running, or the address moved.
      // Trying again every second would not change that.
      if (response.status >= 400 && response.status < 500) return gone();
      const reader = response.body.getReader();
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        pending.push(value);
        feed();
      }
      if (!closed) reconnect("The stream ended");
    } catch (e) {
      if (!closed) reconnect("Connection lost");
    }
  });

  timer = setInterval(() => {
    if (!audio.buffered.length) return;
    const end = audio.buffered.end(audio.buffered.length - 1);
    const ahead = end - audio.currentTime;
    if (audio.paused && ahead >= TARGET) audio.play().catch(() => say("Tap to listen"));
    if (ahead > JUMP) {
      audio.currentTime = end - TARGET;
      audio.playbackRate = 1;
    } else {
      audio.playbackRate = ahead > NUDGE ? 1.05 : 1;
    }
    if (!audio.paused) say(`Live · ${ahead.toFixed(1)} s buffered`);
  }, 250);

  function reconnect(why) {
    close();
    say(`${why} — reconnecting…`);
    setTimeout(() => { if (session === self) session = streamed(); }, 1000);
  }

  function gone() {
    close();
    session = null;
    toggle.setAttribute("aria-pressed", "false");
    toggle.textContent = "Listen";
    say("Not on air here — open the board's link again for the current address");
  }

  function close() {
    closed = true;
    clearInterval(timer);
    abort.abort();
    audio.pause();
    audio.removeAttribute("src");
    audio.load();
  }

  const self = { close };
  return self;
}
